import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { AvatarComponent } from '../../avatar/avatar.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { selectedContactList } from '../../../interfaces/issue.interface';
import { ContactService } from '../../../services/contact/contact.service';
import { MatSelectModule } from '@angular/material/select';
import { FormsModule } from '@angular/forms';
import { IconComponent } from '../../icon/icon.component';
import { ContactFormComponent } from '../contact-form/contact-form.component';
import { ButtonComponent } from '../../button/button.component';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { CommonModule } from '@angular/common';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';

@Component({
  selector: 'choose-contact',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [AvatarComponent, MatTooltipModule, MatSelectModule, FormsModule, IconComponent, ButtonComponent, CommonModule, ContactFormComponent],
  templateUrl: './choose-contact.component.html',
  styleUrl: './choose-contact.component.scss'
})

export class ChooseContactComponent implements OnInit {
  @Input() selectedContacts: selectedContactList[];
  @Input() nCaseid: string;
  @Output() OnEvent = new EventEmitter<toolEvents>();
  @Output() changeContact: EventEmitter<string> = new EventEmitter();
  contactList: selectedContactList[] = [];
  nContactid: string;
  choosedContact: selectedContactList;
  isLoading: boolean = true;
  @Input() ismyfiles: boolean = false;
  showContactForm: boolean = false;
  contactFormData: any = null;
  contactFormMode: 'add' | 'edit' = 'add';
  @Input() nopadding: boolean = false;
  constructor(private contactService: ContactService, private cdr: ChangeDetectorRef, private tost: TostbarService) {
  }


  async ngOnInit() {
    this.contactList = await this.contactService.getContactList(this.nCaseid);
    this.handleSeletedContact();
    if (this.nContactid) {
      this.selectedContact();
      if (this.selectedContacts && this.selectedContacts.length > 0) {
        const ind = this.selectedContacts.findIndex(a => a.nContactid == this.choosedContact.nContactid);
        this.selectedContacts.splice(ind, 1);
        this.selectedContacts.unshift(this.choosedContact);
      }
    }
    this.isLoading = false;
    this.cdr.detectChanges();
  }


  selectedContact() {
    this.choosedContact = this.contactList.find(a => a.nContactid == this.nContactid);
    this.cdr.detectChanges();
  }


  async addContact(x?, permission?) {
    if (this.showContactForm) return;
    if (permission && permission == 'E' && !x) { return }
    let edit_detail;
    if (x) {
      edit_detail = await this.contactService.getContactDetail(x.nContactid);
    }
    this.contactFormData = x ? edit_detail : null;
    this.contactFormMode = x ? 'edit' : 'add';
    this.showContactForm = true;
    this.cdr.detectChanges();
  }


  onContactFormEvent(event: any) {
    if (event.event === 'CLOSE') {
      this.showContactForm = false;
      this.contactFormData = null;
      this.cdr.detectChanges();
    } else if (event.event === 'NEW_ADDED') {
      this.nContactid = event.data.nContactid;
      this.isLoading = true;
      this.showContactForm = false;
      this.contactFormData = null;
      this.ngOnInit();
    }
  }


  SaveContact() {

    if (!this.choosedContact) return;
    const ind = this.selectedContacts.findIndex(a => a.nContactid == this.choosedContact.nContactid);
    if (ind == -1) {
      this.selectedContacts.unshift(this.choosedContact);
      // this.selectedContacts = [...this.selectedContacts]
      this.choosedContact = null;
      this.nContactid = null;
    } else {
      this.tost.openSnackBar('Contact already added', 'E');
    }
    this.cdr.detectChanges();
    this.OnEvent.emit({ event: 'SUBMIT', data: {} });
  }

  view() {
    this.OnEvent.emit({ event: 'VIEW', data: {} });
  }


  handleSeletedContact() {
    if (this.selectedContacts.length && this.contactList.length) {
      for (let index = 0; index < this.selectedContacts.length; index++) {
        const found = this.contactList.find(a => a.nContactid == this.selectedContacts[index].nContactid);
        if (found) {
          this.selectedContacts[index] = found;
        }
      }
    }
  }


  back() {
    // Handle back navigation - you can customize this based on your needs
    this.OnEvent.emit({ event: 'BACK', data: {} });
  }
}
